SET VARIABLE force_wells = (
    SELECT list('{base}/force_2020/wells/' || path)
    FROM read_json('{base}/force_2020/wells/_files.json') AS manifest(path)
);

SELECT WELL, count(*) AS samples
FROM read_parquet(getvariable('force_wells'))
GROUP BY WELL
ORDER BY samples DESC
LIMIT 10;

SET VARIABLE monthly_production = (
    SELECT list('{base}/argentina/monthly_production/' || path)
    FROM read_json('{base}/argentina/monthly_production/_files.json') AS manifest(path)
);

SELECT fecha, prod_pet, prod_gas, prod_agua
FROM read_parquet(getvariable('monthly_production'), hive_partitioning = true)
WHERE anio >= 2023         -- skips the files for 2006 to 2022
  AND idpozo = 160694      -- skips blocks of rows that hold other wells
ORDER BY fecha;

SET VARIABLE force_wells = (
    SELECT list('{base}/force_2020/wells/' || path)
    FROM read_json('{base}/force_2020/wells/_files.json') AS manifest(path)
);

COPY (FROM read_parquet(getvariable('force_wells')))
TO 'force_2020_wells.parquet';
